import {SyntaxKind}from'ts-morph';var C=["a","span","div","Link","label","Label"],O=async({sourceFile:c,config:x})=>{if(!x.style?.startsWith("base-"))return c;let p=10;for(let h=0;h<p;h++){let E=c.getDescendantsOfKind(SyntaxKind.JsxElement).filter(e=>e.getOpeningElement().getAttribute("asChild"));if(E.length===0)break;let N=E.filter(e=>!e.getDescendantsOfKind(SyntaxKind.JsxElement).some(i=>i.getOpeningElement().getAttribute("asChild"))),T=[];for(let e of N){let o=e.getOpeningElement(),i=o.getAttribute("asChild");if(!i)continue;let a=o.getTagNameNode().getText(),r=e.getJsxChildren().find(s=>s.getKind()===SyntaxKind.JsxElement||s.getKind()===SyntaxKind.JsxSelfClosingElement);if(!r){i.remove();continue}let l,n,d;if(r.getKind()===SyntaxKind.JsxSelfClosingElement){let s=r.asKindOrThrow(SyntaxKind.JsxSelfClosingElement);l=s.getTagNameNode().getText(),n=s.getAttributes().map(m=>m.getText()).join(" "),d="";}else {let s=r.asKindOrThrow(SyntaxKind.JsxElement),m=s.getOpeningElement();l=m.getTagNameNode().getText(),n=m.getAttributes().map(f=>f.getText()).join(" "),d=s.getJsxChildren().map(f=>f.getText()).join("");}let u=a==="Button"&&C.includes(l);T.push({parentElement:e,parentTagName:a,childTagName:l,childProps:n,childChildren:d,needsNativeButton:u});}for(let e of T.reverse()){let i=e.parentElement.getOpeningElement().getAttributes().filter(n=>n.getKind()===SyntaxKind.JsxAttribute?n.asKindOrThrow(SyntaxKind.JsxAttribute).getNameNode().getText()!=="asChild":true).map(n=>n.getText()).join(" "),a=e.childProps?`{<${e.childTagName} ${e.childProps} />}`:`{<${e.childTagName} />}`,g=i?`${i} `:"";g+=`render=${a}`,e.needsNativeButton&&(g+=" nativeButton={false}");let r=e.childChildren.trim()?`${e.childChildren}`:"",l=`<${e.parentTagName} ${g}>${r}</${e.parentTagName}>`;e.parentElement.replaceWithText(l);}}return c};export{O as a};